183	    /** Validate, derive and persist a brand-new owner from the submitted fields. */
184	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
185	        normalizeAddress(ownerFieldsDto);
186	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
187	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
188	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
189	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
190	        DisposableEmailDomainValidator.validate(owner.getEmail());
191	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
192	        RegistrationDateValidator.validateNotFuture(owner.getRegistrationDate());
193	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
194	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
195	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
196	        owner.setHouseholdId(HouseholdKey.idFor(owner.getLastName(), owner.getPostcode()));
197	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
198	            // Reject only a true duplicate (an owner identical to one already on file); a distinct
199	            // new household member is allowed but flagged as a possible duplicate. A declared member
200	            // bypasses this block, and is not a suspected duplicate.
201	            this.householdDuplicateValidator.rejectIfDuplicate(owner);
202	            this.possibleDuplicateOwnerDetector.findPossibleDuplicateOf(owner)
203	                .ifPresent(owner::setPossibleDuplicateOf);
204	        }
205	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
206	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
207	        owner.setHouseholdSize(this.householdSizeCounter.count(owner.getHouseholdId()));
208	        owner.setMembershipLevelCap(this.householdMembershipLevelCap.ceilingFor(owner.getHouseholdId()));
209	        String region = RegionResolver.regionFor(owner.getPostcode(), owner.getCity());
210	        String memberId = MemberIdGenerator.generate(region, owner.getTelephone(), owner.getLastName(),
211	            owner.getRegistrationDate());
