235	    /**
236	     * Normalize the submitted address fields and resolve the effective {@code address}. The
237	     * structured lines are normalized in place; when a non-blank {@code addressLine1} is supplied it
238	     * takes precedence and {@code address} is composed from the normalized lines, otherwise the flat
239	     * {@code address} input is normalized and kept for backward compatibility.
240	     */
241	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
242	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
243	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
244	        ownerFieldsDto.setAddressLine1(line1);
245	        ownerFieldsDto.setAddressLine2(line2);
246	        if (line1 != null && !line1.isBlank()) {
247	            ownerFieldsDto.setAddress(AddressNormalizer.compose(line1, line2));
248	        } else {
249	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
250	        }
251	    }
